     1→#!/usr/bin/env node
     2→
     3→import { google } from 'googleapis';
     4→import minimist from 'minimist';
     5→import { getAuthClient, parseAccountArg } from './auth/auth-utils.js';
     6→import { logAction } from './action-logger.js';
     7→
     8→function createEmailMessage(to, subject, body, options = {}) {
     9→  const { cc, bcc, html, replyTo } = options;
    10→
    11→  const headers = [
    12→    `To: ${to}`,
    13→    `Subject: ${subject}`,
    14→  ];
    15→
    16→  if (cc) headers.push(`Cc: ${cc}`);
    17→  if (bcc) headers.push(`Bcc: ${bcc}`);
    18→  if (replyTo) headers.push(`Reply-To: ${replyTo}`);
    19→
    20→  headers.push('Content-Type: text/html; charset=utf-8');
    21→  headers.push('');
    22→
    23→  const message = headers.join('\r\n') + (html || body);
    24→
    25→  return Buffer.from(message)
    26→    .toString('base64')
    27→    .replace(/\+/g, '-')
    28→    .replace(/\//g, '_')
    29→    .replace(/=+$/, '');
    30→}
    31→
    32→async function sendEmail(args) {
    33→  // Validate required args
    34→  if (!args.to || !args.subject || !args.body) {
    35→    throw new Error('Missing required arguments: --to, --subject, and --body are required');
    36→  }
    37→
    38→  // Get authenticated client for specified account (or default)
    39→  const accountId = parseAccountArg(args);
    40→  const oauth2Client = await getAuthClient(accountId);
    41→
    42→  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });
    43→
    44→  // Create email
    45→  const encodedMessage = createEmailMessage(
    46→    args.to,
    47→    args.subject,
    48→    args.body,
    49→    {
    50→      cc: args.cc,
    51→      bcc: args.bcc,
    52→      html: args.html,
    53→      replyTo: args['reply-to']
    54→    }
    55→  );
    56→
    57→  // Send email
    58→  const result = await gmail.users.messages.send({
    59→    userId: 'me',
    60→    requestBody: {
    61→      raw: encodedMessage
    62→    }
    63→  });
    64→
    65→  return {
    66→    success: true,
    67→    messageId: result.data.id,
    68→    threadId: result.data.threadId,
    69→    to: args.to,
    70→    subject: args.subject,
    71→    account: accountId || 'default'
    72→  };
    73→}
    74→
    75→// Main execution
    76→const args = minimist(process.argv.slice(2));
    77→const startTime = Date.now();
    78→
    79→sendEmail(args)
    80→  .then(result => {
    81→    // Log the action
    82→    logAction('send', args, result, {
    83→      account: result.account,
    84→      duration: Date.now() - startTime
    85→    });
    86→
    87→    console.log(JSON.stringify(result, null, 2));
    88→  })
    89→  .catch(error => {
    90→    const errorResult = {
    91→      success: false,
    92→      error: error.message
    93→    };
    94→
    95→    // Log the failed action
    96→    logAction('send', args, errorResult, {
    97→      account: args.account || 'default',
    98→      duration: Date.now() - startTime,
    99→      failed: true
   100→    });
   101→
   102→    console.error(JSON.stringify(errorResult, null, 2));
   103→    process.exit(1);
   104→  });
