input.content:
import { google } from 'googleapis';
import { readFileSync } from 'fs';

// Load credentials and tokens
const credentials = JSON.parse(readFileSync('/root/auth/gmail/credentials.json', 'utf8'));
const tokens = JSON.parse(readFileSync('/root/auth/gmail/tokens.json', 'utf8'));
const account = tokens.accounts.default;

const { client_id, client_secret } = credentials.installed;
const oauth2Client = new google.auth.OAuth2(client_id, client_secret);

// Set credentials - set the refresh_token so it can refresh on 401
oauth2Client.setCredentials({
    access_token: account.access_token,
    refresh_token: account.refresh_token,
    token_type: 'Bearer',
    // Don't set expiry_date to force_refresh behavior on 401
});

// The googleapis library should automatically refresh on 401
const gmail = google.gmail({ version: 'v1', auth: oauth2Client });

oauth2Client.on('tokens', (tokens) => {
    console.log('New tokens received:', JSON.stringify({
        scope: tokens.scope,
        expiry_date: tokens.expiry_date,
        token_type: tokens.token_type
    }));
});

try {
    // Force refresh first
    const { credentials: newCreds } = await oauth2Client.refreshAccessToken();
    console.log('Refreshed scopes:', newCreds.scope);

    const profile = await gmail.users.getProfile({ userId: 'me' });
    console.log('Profile:', JSON.stringify(profile.data));
} catch (e) {
    console.log('Error:', e.message);
    console.log('Code:', e.code);
}

